      scanAnalyzedSpeech: 'கழிவு பொருள் பகுப்பாய்வு செய்யப்பட்டது. {matName} கண்டறியப்பட்டது, தரம் {grade}. மதிப்பு: கிலோவுக்கு {rate} ரூபாய்.',
      pickupBookedSpeech: '{name}-உடன் வீட்டு வாசல் பிக்கப் பதிவு செய்யப்பட்டது. மதிப்பிடப்பட்ட வருகை {mins} நிமிடங்களில்.',
