      lotSentSpeech: 'லாட் உருவாக்கப்பட்டு {name}-க்கு அனுப்பப்பட்டது.',
      paymentConfirmedSpeech: 'லாட் {lotId}-க்கான பணம் உறுதி செய்யப்பட்டது. சான்றிதழ் வழங்கப்பட்டது.',
      wholesaleRatesSpeech: 'வகை வாரியான மொத்த கழிவு விலைகள். ஒரு மறுசுழற்சியாளர் புதிய விலைகளை வெளியிடும்போது மட்டுமே விலைகள் புதுப்பிக்கப்படும்.',
      inventorySpeech: 'மொத்த இருப்பு: {weight} கிலோகிராம். தற்போதைய சந்தை மதிப்பு: {value} ரூபாய். எதிர்பார்க்கப்படும் மொத்த லாபம்: {profit} ரூபாய்.',
      dealerProfileSpeech: '{yard}-இன் உரிமையாளர் {name}-இன் சுயவிவரம். மொத்த வாராந்திர சேகரிப்பு: {count} பரிவர்த்தனைகளில் {weight} கிலோகிராம்.',
      recyclerPortalSpeech: 'அங்கீகரிக்கப்பட்ட மறுசுழற்சியாளர் இணக்கத் தளம். CPCB அங்கீகரிக்கப்பட்ட வசதி.',

      assistantPriceAnswer: '{matName}: வீட்டு வாசல் உத்தரவாத விலை கிலோவுக்கு ₹{customerRate}, அல்லது மொத்த மறுசுழற்சியாளர் விலை கிலோவுக்கு ₹{recyclerRate}.',
      assistantNoDealersAnswer: 'இன்னும் எந்த கழிவு வியாபாரியும் இந்த தளத்தில் பதிவு செய்யப்படவில்லை.',
      assistantNearestDealerAnswer: 'அருகிலுள்ள பதிவு செய்யப்பட்ட வியாபாரி {name}, {shop}, {location}-இல் உள்ளார். மதிப்பிடப்பட்ட வருகை: {mins} நிமிடங்கள்.',
      assistantFallbackAnswer: 'EcoScrap AI உங்களை நியாயமான, உத்தரவாத வீட்டு வாசல் ரொக்கத்திற்காக சரிபார்க்கப்பட்ட கழிவு வியாபாரிகளுடன் இணைக்கிறது. உங்கள் கழிவு மற்றும் அதன் தரத்தை அடையாளம் காண புகைப்படத்தை ஸ்கேன் செய்யவும், நேரடி விலை பலகையைப் பார்க்கவும், பின்னர் பிக்கப் கோரவும் — சான்றளிக்கப்பட்ட தராசுடன் ஒரு வியாபாரி வருவார்.',

